class RotatedBillion:
    """A billion distinct numbers: 5 * j - 7_000_000 for j = 0, 1, 2, ... sorted, then rotated so that position 0 holds j = shift.
    It supports only len() and nums[i], and counts every look."""
    size = 1_000_000_000

    def __init__(self, shift):
        self.shift = shift
        self.looks = 0

    def __len__(self):
        return self.size

    def __getitem__(self, i):
        if not isinstance(i, int):
            raise TypeError("a sequence of a billion numbers can only be read one position at a time, nums[i] (no slices)")
        self.looks += 1
        if self.looks > 500:
            raise AssertionError("looked at more than 500 elements of a list of a billion numbers: this search needs about 30 steps")
