def find_min(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1          # the drop (the minimum) is to the right of mid
        else:
            hi = mid              # mid itself may be the minimum, so keep it
    return nums[lo]
